//go:build amd64

package floats

// The AVX2+FMA kernel of CDotC (cdot.go), generated by go-asmgen (cdot_amd64_gen.go) into
// cdot_amd64.s: blocks of four complex numbers, writing the folded lanes of the two sums
// to out (out[0:4] the sum of a*b, out[4:8] the sum of a*swap(b)); the Go code does the
// last complex numbers. The gate is hasAVX2FMA (kernels_amd64.go); the portable loop
// otherwise. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func cdotcAVX2(a, b, out []float64)

func cdotc(a, b []float64) (re, im float64) {
	if !hasAVX2FMA {
		return cdotcTail(a, b, 0)
	}
	var out [8]float64
	cdotcAVX2(a, b, out[:])
	re, im = (out[0]+out[1])+(out[2]+out[3]), (out[4]-out[5])+(out[6]-out[7])
	tr, ti := cdotcTail(a, b, len(a)&^7)
	return re + tr, im + ti
}
